ValidationRule.errorConditionFormula:
AND(
ISCHANGED(Status),

OR(

/* Technical Evaluation */
AND(
ISPICKVAL(Status , "Technical Evaluation"),
ISPICKVAL(Waiting_For__c , "")
),

/* Commercial Processing */
AND(
ISPICKVAL(Status , "Commercial Processing"),
ISPICKVAL(Waiting_For__c , "")
),

/* Technical Processing */
AND(
ISPICKVAL(Status , "Technical Processing"),
ISPICKVAL(Waiting_For__c , "")
)

)
)
